Object.assign(SNIP,{});PRESET_NOTES["l47"]={"Ví dụ: Bảng LCS": "Bảng điền theo hàng. Ô góc dưới phải là đáp án: 4 (ví dụ BCBA hoặc BDAB). Hàng i ứng với tiền tố i ký tự của s, nên ký tự cần so là s[i − 1].", "Ví dụ: Khoảng cách sửa": "3 phép: kitten → sitten (thay) → sittin (thay) → sitting (chèn). Hàng 0 và cột 0 không phải 0 như LCS mà là số phép chèn, xóa hết.", "Ví dụ: Truy vết để in LCS": "Từ ô (n, m), mỗi bước đi về ô đã tạo ra giá trị hiện tại: chéo nếu hai ký tự khớp (ghi ký tự), không thì lên hoặc sang trái theo ô lớn hơn. Ký tự thu được theo thứ tự ngược, đảo lại được BCBA.", "Ví dụ: Chỉ giữ hai hàng": "Mỗi hàng chỉ đọc hàng ngay trên, nên bộ nhớ O(m) thay vì O(n·m). Đổi lại, không còn bảng để truy vết.", "Lỗi: quên khởi tạo hàng 0 và cột 0": "In 2 thay vì 3 (sunday → saturday cần chèn a, chèn t, thay n → r): bảng tưởng rằng biến một xâu thành xâu rỗng không tốn phép nào, nên hai phép chèn ở đầu được tính miễn phí. Với LCS, hàng 0 bằng 0 là đúng; với khoảng cách sửa thì không."};EX_HINTS["l47"]=[["Hàng 0 và cột 0 bằng 0 (mảng toàn cục đã là 0).", "Hai ký tự cuối s[i−1], t[j−1] bằng nhau: ô chéo + 1. Khác nhau: max của ô trên và ô trái.", "Đệ quy thử bỏ ký tự này hay ký tự kia mà không nhớ là cấp số mũ."], ["dp[i][0] = i (xóa hết i ký tự), dp[0][j] = j (chèn j ký tự).", "Hai ký tự cuối bằng nhau: dp[i][j] = dp[i−1][j−1]. Khác nhau: 1 + min của ô chéo (thay), ô trên (xóa), ô trái (chèn).", "Kiểm tra tay: horse → ros cần 3 phép."], ["Trạng thái phải là “kết thúc tại” (giống LIS): dp[i][j] là đoạn chung dài nhất kết thúc đúng tại s[i−1] và t[j−1].", "Hai ký tự bằng nhau: dp[i][j] = dp[i−1][j−1] + 1. Khác nhau: 0 (không lấy max như LCS).", "Đáp án là ô lớn nhất của cả bảng, không phải ô góc."]];
/* ===================== BÀI 47 · Xâu con chung dài nhất (LCS) và khoảng cách sửa ===================== */
/* Bài 47 · Xâu con chung dài nhất (LCS) và khoảng cách sửa
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR47=[{label:"Ví dụ: Bảng LCS",input:"",code:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[8][7];                          // hàng 0, cột 0 đều là 0\n\nint main() {\n    string s = \"ABCBDAB\", t = \"BDCABA\";\n    int n = s.size(), m = t.size();\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++) {\n            if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;   // ghép hai ký tự cuối\n            else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);           // bỏ một ký tự cuối\n        }\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}],py:{code:"s, t = \"ABCBDAB\", \"BDCABA\"\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]   # hàng 0, cột 0 đều là 0\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if s[i - 1] == t[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1] + 1  # ghép hai ký tự cuối\n        else:\n            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])   # bỏ một ký tự cuối\nprint(dp[n][m])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"ABCBDAB\", t = \"BDCABA\";\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= m; j++)\n            {\n                if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;   // ghép hai ký tự cuối\n                else dp[i][j] = Math.Max(dp[i - 1][j], dp[i][j - 1]);       // bỏ một ký tự cuối\n            }\n        Console.WriteLine(dp[n][m]);\n    }\n}"}},{label:"Ví dụ: Khoảng cách sửa",input:"",code:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[7][8];\n\nint main() {\n    string s = \"kitten\", t = \"sitting\";\n    int n = s.size(), m = t.size();\n    for (int i = 0; i <= n; i++) dp[i][0] = i;   // xóa hết\n    for (int j = 0; j <= m; j++) dp[0][j] = j;   // chèn hết\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++) {\n            if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n            else dp[i][j] = 1 + min(dp[i - 1][j - 1], min(dp[i - 1][j], dp[i][j - 1]));   // thay, xóa, chèn\n        }\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}],py:{code:"s, t = \"kitten\", \"sitting\"\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nfor i in range(n + 1):\n    dp[i][0] = i                       # xóa hết\nfor j in range(m + 1):\n    dp[0][j] = j                       # chèn hết\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if s[i - 1] == t[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1]\n        else:\n            dp[i][j] = 1 + min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1])   # thay, xóa, chèn\nprint(dp[n][m])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"kitten\", t = \"sitting\";\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        for (int i = 0; i <= n; i++) dp[i][0] = i;   // xóa hết\n        for (int j = 0; j <= m; j++) dp[0][j] = j;   // chèn hết\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= m; j++)\n            {\n                if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n                else dp[i][j] = 1 + Math.Min(dp[i - 1][j - 1], Math.Min(dp[i - 1][j], dp[i][j - 1]));   // thay, xóa, chèn\n            }\n        Console.WriteLine(dp[n][m]);\n    }\n}"}},{label:"Ví dụ: Truy vết để in LCS",input:"",code:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[8][7];\n\nint main() {\n    string s = \"ABCBDAB\", t = \"BDCABA\";\n    int n = s.size(), m = t.size();\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++)\n            dp[i][j] = (s[i - 1] == t[j - 1]) ? dp[i - 1][j - 1] + 1 : max(dp[i - 1][j], dp[i][j - 1]);\n    string kq = \"\";\n    int i = n, j = m;\n    while (i > 0 && j > 0) {           // đi ngược từ góc dưới phải\n        if (s[i - 1] == t[j - 1]) {\n            kq += s[i - 1];            // ký tự này nằm trong LCS\n            i--; j--;\n        } else if (dp[i - 1][j] >= dp[i][j - 1]) i--;\n        else j--;\n    }\n    reverse(kq.begin(), kq.end());\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}],py:{code:"s, t = \"ABCBDAB\", \"BDCABA\"\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        dp[i][j] = dp[i - 1][j - 1] + 1 if s[i - 1] == t[j - 1] else max(dp[i - 1][j], dp[i][j - 1])\nkq = []\ni, j = n, m\nwhile i > 0 and j > 0:                 # đi ngược từ góc dưới phải\n    if s[i - 1] == t[j - 1]:\n        kq.append(s[i - 1])            # ký tự này nằm trong LCS\n        i -= 1\n        j -= 1\n    elif dp[i - 1][j] >= dp[i][j - 1]:\n        i -= 1\n    else:\n        j -= 1\nprint(\"\".join(reversed(kq)))"},cs:{code:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"ABCBDAB\", t = \"BDCABA\";\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= m; j++)\n                dp[i][j] = s[i - 1] == t[j - 1] ? dp[i - 1][j - 1] + 1 : Math.Max(dp[i - 1][j], dp[i][j - 1]);\n        var kq = new StringBuilder();\n        int x = n, y = m;\n        while (x > 0 && y > 0)                 // đi ngược từ góc dưới phải\n        {\n            if (s[x - 1] == t[y - 1])\n            {\n                kq.Insert(0, s[x - 1]);        // ký tự này nằm trong LCS\n                x--; y--;\n            }\n            else if (dp[x - 1][y] >= dp[x][y - 1]) x--;\n            else y--;\n        }\n        Console.WriteLine(kq.ToString());\n    }\n}",viz:[{type:"grid",of:"dp",ptr:["x","y"]}]}},{label:"Ví dụ: Chỉ giữ hai hàng",input:"",code:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint truoc[7], hien[7];                 // hàng i-1 và hàng i\n\nint main() {\n    string s = \"ABCBDAB\", t = \"BDCABA\";\n    int n = s.size(), m = t.size();\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= m; j++) {\n            if (s[i - 1] == t[j - 1]) hien[j] = truoc[j - 1] + 1;\n            else hien[j] = max(truoc[j], hien[j - 1]);\n        }\n        for (int j = 0; j <= m; j++) truoc[j] = hien[j];   // hàng mới thành hàng trước\n    }\n    cout << truoc[m] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"truoc",ptr:["j"]},{type:"cells",of:"hien",ptr:["j"]}],py:{code:"s, t = \"ABCBDAB\", \"BDCABA\"\nn, m = len(s), len(t)\ntruoc = [0] * (m + 1)                  # hàng i-1\nfor i in range(1, n + 1):\n    hien = [0] * (m + 1)               # hàng i\n    for j in range(1, m + 1):\n        if s[i - 1] == t[j - 1]:\n            hien[j] = truoc[j - 1] + 1\n        else:\n            hien[j] = max(truoc[j], hien[j - 1])\n    truoc = hien                       # hàng mới thành hàng trước\nprint(truoc[m])",viz:[{type:"cells",of:"truoc",ptr:["j"]},{type:"cells",of:"hien",ptr:["j"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"ABCBDAB\", t = \"BDCABA\";\n        int n = s.Length, m = t.Length;\n        int[] truoc = new int[m + 1], hien = new int[m + 1];   // hàng i-1 và hàng i\n        for (int i = 1; i <= n; i++)\n        {\n            for (int j = 1; j <= m; j++)\n            {\n                if (s[i - 1] == t[j - 1]) hien[j] = truoc[j - 1] + 1;\n                else hien[j] = Math.Max(truoc[j], hien[j - 1]);\n            }\n            (truoc, hien) = (hien, truoc);     // hàng mới thành hàng trước\n        }\n        Console.WriteLine(truoc[m]);\n    }\n}"}},{label:"Lỗi: quên khởi tạo hàng 0 và cột 0",input:"",code:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[7][9];                          // toàn 0\n\nint main() {\n    string s = \"sunday\", t = \"saturday\";\n    int n = s.size(), m = t.size();\n    // thiếu: dp[i][0] = i và dp[0][j] = j\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++) {\n            if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n            else dp[i][j] = 1 + min(dp[i - 1][j - 1], min(dp[i - 1][j], dp[i][j - 1]));\n        }\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}],py:{code:"s, t = \"sunday\", \"saturday\"\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]   # toàn 0\n# thiếu: dp[i][0] = i và dp[0][j] = j\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if s[i - 1] == t[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1]\n        else:\n            dp[i][j] = 1 + min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1])\nprint(dp[n][m])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"sunday\", t = \"saturday\";\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        // thiếu: dp[i][0] = i và dp[0][j] = j\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= m; j++)\n            {\n                if (s[i - 1] == t[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n                else dp[i][j] = 1 + Math.Min(dp[i - 1][j - 1], Math.Min(dp[i - 1][j], dp[i][j - 1]));\n            }\n        Console.WriteLine(dp[n][m]);\n    }\n}"}}];
