makeEx2(document.getElementById("ex-l47"),sim47,[{t:"Xâu con chung dài nhất",d:"Đầu vào: hai dòng, mỗi dòng một xâu chữ thường dài 1 … 1000. Đầu ra: độ dài xâu con chung dài nhất (các ký tự giữ thứ tự nhưng không cần liền nhau).",tests:[{in:"abcbdab\nbdcaba",out:"4"},{in:"abc\nabc",out:"3"},{in:"abc\ndef",out:"0"},{in:"a\naaaa",out:"1"},{in:"aggtab\ngxtxayb",out:"4"},{in:"caddccddadaaacdacdbbcdbacccbbabcacdcabcbdadccbccadcdcbabddcbdabaacddca\ncdcabbcdbbdbbabcdacdaadacacabbdbddaabbcabadaaacacbbcadcaaddccdbaaddadacdabccbdaa",out:"47"}],start:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[1001][1001];\n\nint main() {\n    string s, t;\n    cin >> s >> t;\n    int n = s.size(), m = t.size();\n    // dp[i][j]: LCS của i ký tự đầu của s và j ký tự đầu của t\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",py:{start:"s = input()\nt = input()\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\n# dp[i][j]: LCS của i ký tự đầu của s và j ký tự đầu của t\nprint(dp[n][m])",hints:["Hàng 0 và cột 0 bằng 0. Tạo bảng bằng [[0] * (m + 1) for _ in range(n + 1)], đừng dùng [[0] * (m + 1)] * (n + 1) (các hàng dùng chung một list).","Hai ký tự cuối s[i−1], t[j−1] bằng nhau: ô chéo + 1. Khác nhau: max của ô trên và ô trái.","Đệ quy thử bỏ ký tự này hay ký tự kia mà không nhớ là cấp số mũ."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine(), t = Console.ReadLine();\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        // dp[i][j]: LCS của i ký tự đầu của s và j ký tự đầu của t\n        Console.WriteLine(dp[n][m]);\n    }\n}",hints:["Hàng 0 và cột 0 bằng 0 (mảng mới tạo đã là 0).","Hai ký tự cuối s[i−1], t[j−1] bằng nhau: ô chéo + 1. Khác nhau: max của ô trên và ô trái.","Đệ quy thử bỏ ký tự này hay ký tự kia mà không nhớ là cấp số mũ."]}},{t:"Sửa lỗi chính tả",d:"Đầu vào: hai dòng, mỗi dòng một xâu chữ thường dài 1 … 1000. Đầu ra: số phép ít nhất (chèn, xóa hoặc thay một ký tự) để biến xâu thứ nhất thành xâu thứ hai.",tests:[{in:"kitten\nsitting",out:"3"},{in:"abc\nabc",out:"0"},{in:"a\nb",out:"1"},{in:"abc\nx",out:"3"},{in:"intention\nexecution",out:"5"},{in:"horse\nros",out:"3"},{in:"ddcabcacddaadccdbaacdccaadcacadccbcbdcddcabdaadddccacabdcddb\nccaddbdabbaddabdbdabadadddcadaaddabdddadcdbcdabdcacdacadabbccaacbdbdda",out:"34"}],start:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[1001][1001];\n\nint main() {\n    string s, t;\n    cin >> s >> t;\n    int n = s.size(), m = t.size();\n    // khởi tạo hàng 0, cột 0; rồi điền theo hàng\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",py:{start:"s = input()\nt = input()\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\n# khởi tạo hàng 0, cột 0; rồi điền theo hàng\nprint(dp[n][m])",hints:["dp[i][0] = i (xóa hết i ký tự), dp[0][j] = j (chèn j ký tự).","Hai ký tự cuối bằng nhau: dp[i][j] = dp[i−1][j−1]. Khác nhau: 1 + min của ô chéo (thay), ô trên (xóa), ô trái (chèn).","Kiểm tra tay: horse → ros cần 3 phép."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine(), t = Console.ReadLine();\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        // khởi tạo hàng 0, cột 0; rồi điền theo hàng\n        Console.WriteLine(dp[n][m]);\n    }\n}",hints:["dp[i][0] = i (xóa hết i ký tự), dp[0][j] = j (chèn j ký tự).","Hai ký tự cuối bằng nhau: dp[i][j] = dp[i−1][j−1]. Khác nhau: 1 + min của ô chéo (thay), ô trên (xóa), ô trái (chèn).","Kiểm tra tay: horse → ros cần 3 phép."]}},{t:"Đoạn chung dài nhất",d:"Khác bài LCS: lần này các ký tự chung phải nằm <b>liền nhau<\/b> trong cả hai xâu. Đầu vào: hai dòng, mỗi dòng một xâu chữ thường dài 1 … 1000. Đầu ra: độ dài đoạn (xâu con liên tiếp) chung dài nhất; không có ký tự chung thì in 0.",tests:[{in:"abcbdab\nbdcaba",out:"2"},{in:"abcdxyz\nxyzabcd",out:"4"},{in:"abc\ndef",out:"0"},{in:"aaaa\naa",out:"2"},{in:"zxabcdezy\nyzabcdezx",out:"6"},{in:"bababaaaaaaaaaaaabbabbababaaaababbbbbbbbaabababaabbababbbaaaabbaabaaba\nabbaabbaababbbabbbbbababbaababbabbbaabbaaaabbabaaababbabbabbbaaabaaaaabbaabbbaab",out:"9"}],start:"#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint dp[1001][1001];\n\nint main() {\n    string s, t;\n    cin >> s >> t;\n    int n = s.size(), m = t.size();\n    int best = 0;\n    // dp[i][j]: độ dài đoạn chung dài nhất KẾT THÚC tại s[i-1] và t[j-1]\n    cout << best << \"\\n\";\n    return 0;\n}",py:{start:"s = input()\nt = input()\nn, m = len(s), len(t)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nbest = 0\n# dp[i][j]: độ dài đoạn chung dài nhất KẾT THÚC tại s[i-1] và t[j-1]\nprint(best)",hints:["Trạng thái phải là “kết thúc tại” (giống LIS): dp[i][j] là đoạn chung dài nhất kết thúc đúng tại s[i−1] và t[j−1].","Hai ký tự bằng nhau: dp[i][j] = dp[i−1][j−1] + 1. Khác nhau: 0 (bảng đã là 0 sẵn).","Đáp án là ô lớn nhất của cả bảng, không phải ô góc."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine(), t = Console.ReadLine();\n        int n = s.Length, m = t.Length;\n        int[][] dp = new int[n + 1][];\n        for (int i = 0; i <= n; i++) dp[i] = new int[m + 1];\n        int best = 0;\n        // dp[i][j]: độ dài đoạn chung dài nhất KẾT THÚC tại s[i-1] và t[j-1]\n        Console.WriteLine(best);\n    }\n}",hints:["Trạng thái phải là “kết thúc tại” (giống LIS): dp[i][j] là đoạn chung dài nhất kết thúc đúng tại s[i−1] và t[j−1].","Hai ký tự bằng nhau: dp[i][j] = dp[i−1][j−1] + 1. Khác nhau: 0 (mảng đã là 0 sẵn).","Đáp án là ô lớn nhất của cả bảng, không phải ô góc."]}}]);

